// 事件总线类型与工厂：通用 pub/sub，无 DOM / 框架依赖；
// 支持可选泛型事件映射，未传泛型时退化为字符串通道 + unknown 载荷。

// 默认事件映射：键为字符串、载荷为 unknown，用于不传泛型时保持向后兼容。
export type DefaultEventMap = Record<string, unknown>;

// 事件处理函数：接收载荷，无返回值。
export type EventHandler<T = unknown> = (payload: T) => void;

// 通用事件总线接口：on / once 返回解绑函数；has 支持检查通道或具体 handler 是否注册。
export interface EventBus<TEventMap extends Record<string, unknown> = DefaultEventMap> {
  clear: () => void;
  emit: <K extends keyof TEventMap & string>(type: K, payload: TEventMap[K]) => void;
  has: <K extends keyof TEventMap & string>(type: K, handler?: EventHandler<TEventMap[K]>) => boolean;
  off: <K extends keyof TEventMap & string>(type: K, handler: EventHandler<TEventMap[K]>) => void;
  on: <K extends keyof TEventMap & string>(type: K, handler: EventHandler<TEventMap[K]>) => () => void;
  once: <K extends keyof TEventMap & string>(type: K, handler: EventHandler<TEventMap[K]>) => () => void;
}

// 创建通用事件总线：基于 Map<type, Set<handler>>，提供 on / once / off / emit / has / clear。
export const createEventBus = <
  TEventMap extends Record<string, unknown> = DefaultEventMap,
>(): EventBus<TEventMap> => {
  const handlers = new Map<string, Set<EventHandler<unknown>>>();

  // 清空当前总线上的全部订阅。
  const clear = () => {
    handlers.clear();
  };

  // 向指定事件通道广播载荷。
  const emit = <K extends keyof TEventMap & string>(type: K, payload: TEventMap[K]) => {
    const scopedHandlers = handlers.get(type);
    if (!scopedHandlers) {
      return;
    }
    // 复制一份再遍历：防止 handler 内部调用 off 修改集合导致跳过相邻订阅。
    // 单个 handler 抛错时仅记录、不中断后续派发，与 mitt / nanoevents / Node EventEmitter 默认行为一致。
    [...scopedHandlers].forEach((handler) => {
      try {
        handler(payload);
      } catch (error) {
        console.error(`[EventBus] handler for "${type}" threw:`, error);
      }
    });
  };

  // 解绑单个事件处理函数；通道空时连带删除键，避免 has 在仅有空 Set 时误判。
  const off = <K extends keyof TEventMap & string>(type: K, handler: EventHandler<TEventMap[K]>) => {
    const scopedHandlers = handlers.get(type);
    if (!scopedHandlers) {
      return;
    }
    scopedHandlers.delete(handler as EventHandler<unknown>);
    if (scopedHandlers.size === 0) {
      handlers.delete(type);
    }
  };

  // 订阅单个事件通道，返回幂等的解绑函数。
  const on = <K extends keyof TEventMap & string>(type: K, handler: EventHandler<TEventMap[K]>) => {
    let scopedHandlers = handlers.get(type);
    if (!scopedHandlers) {
      scopedHandlers = new Set();
      handlers.set(type, scopedHandlers);
    }
    scopedHandlers.add(handler as EventHandler<unknown>);
    return () => {
      off(type, handler);
    };
  };

  // 订阅一次性事件：首次触发后自动解绑；返回值可在触发前提前取消。
  // 注意：内部以 wrapped 包装注册到 Set，因此 off(type, originalHandler) /
  // has(type, originalHandler) 都无法匹配 once 注册项；要取消请使用本函数的返回值。
  const once = <K extends keyof TEventMap & string>(type: K, handler: EventHandler<TEventMap[K]>) => {
    // 包装层负责自调 off，保证即使外部 handler 抛错也只触发一次。
    const wrapped: EventHandler<TEventMap[K]> = (payload) => {
      off(type, wrapped);
      handler(payload);
    };
    return on(type, wrapped);
  };

  // 判断通道是否有任意订阅者；传入 handler 时判断该 handler 是否注册在通道上。
  // once 注册项以包装函数存在，不会与原始 handler 引用匹配，详见 once 注释。
  const has = <K extends keyof TEventMap & string>(type: K, handler?: EventHandler<TEventMap[K]>) => {
    const scopedHandlers = handlers.get(type);
    if (!scopedHandlers) {
      return false;
    }
    if (handler === undefined) {
      return scopedHandlers.size > 0;
    }
    return scopedHandlers.has(handler as EventHandler<unknown>);
  };

  return {
    clear,
    emit,
    has,
    off,
    on,
    once,
  };
};
