export function isMobileDevice(ua: string | null) {
  if (!ua) return false;
  if (/android|webos|iphone|ipod|blackberry|iemobile|opera mini/i.test(ua)) {
    return true;
  } else {
    return false;
  }
}

export const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

export const pf = <T, U = any>() => {
  let resolve!: (value: T | PromiseLike<T>) => void;
  let reject!: (reason?: U) => void;
  const promise = new Promise<T>((_resolve, _reject) => {
    resolve = _resolve;
    reject = _reject;
  });
  return { promise, reject, resolve };
};

export const jump = (url: string, blank = true) => {
  const a = document.createElement('a');
  a.href = url;
  if (blank) {
    a.target = '_blank';
  }
  a.click();
};

export const download = (url: string, name?: string) => {
  const a = document.createElement('a');
  a.href = url;
  if (name) {
    a.download = name;
  }
  a.click();
};

export const getSuffix = (file: File | string) => {
  const name = typeof file === 'string' ? new URL(file).pathname : file.name;
  let suffix = name.split('.').pop()?.toLowerCase();
  if (file instanceof File) {
    suffix = suffix || file.type.split('/').pop();
  }
  return suffix;
};

export const readFileAsDataURL = (file: File): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result as string);
    reader.onerror = reject;
    reader.readAsDataURL(file);
  });
};

// 把数值钳制在 [min, max] 区间内，超出则返回最近的边界值。
export const clamp = (value: number, min: number, max: number): number => {
  if (Number.isNaN(value)) return min;
  return Math.max(min, Math.min(max, value));
};

// 把字节数格式化为人类可读的字符串（B/KB/MB/GB/TB），默认保留 2 位小数。
export const formatBytes = (bytes: number, fractionDigits = 2): string => {
  if (!Number.isFinite(bytes) || bytes <= 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB', 'TB'];
  let i = 0;
  let value = bytes;
  while (value >= 1024 && i < units.length - 1) {
    value /= 1024;
    i++;
  }
  return `${value.toFixed(fractionDigits)} ${units[i]}`;
};
